<?php
require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('coordinator');$err='';$ownDept=(int)($u['department_id']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$session=(int)($_POST['academic_session_id']??0);$key=(string)($_POST['milestone_key']??'');$title=post_string('title',160);$due=(string)($_POST['due_at']??'');$dept=$ownDept?:((int)($_POST['department_id']??0)?:null);$allowed=['idea','proposal','chapter_1','chapter_2','chapter_3','chapter_4','chapter_5','final_submission','evaluation'];
 if(!in_array($key,$allowed,true)||!$title||!strtotime($due))$err='Enter a valid deadline title, stage, and due date.';
 else{db()->prepare('INSERT INTO deadlines(academic_session_id,department_id,milestone_key,title,due_at,created_by) VALUES(?,?,?,?,?,?)')->execute([$session,$dept,$key,date('Y-m-d H:i:s',strtotime($due)),$u['id']]);audit('deadline_created','deadline',(int)db()->lastInsertId(),$title);flash('success','Deadline saved.');redirect('coordinator/deadlines.php');}
}
$sessions=db()->query('SELECT id,name FROM academic_sessions ORDER BY starts_on DESC')->fetchAll();$q=db()->prepare('SELECT id,name FROM departments WHERE is_active=1'.($ownDept?' AND id=?':'').' ORDER BY name');$q->execute($ownDept?[$ownDept]:[]);$departments=$q->fetchAll();$q=db()->prepare('SELECT d.*,s.name session_name,dep.name department FROM deadlines d JOIN academic_sessions s ON s.id=d.academic_session_id LEFT JOIN departments dep ON dep.id=d.department_id'.($ownDept?' WHERE d.department_id IS NULL OR d.department_id=?':'').' ORDER BY due_at DESC');$q->execute($ownDept?[$ownDept]:[]);$rows=$q->fetchAll();$pageTitle='Project Deadlines';$crumbTrail=['Deadlines'];require dirname(__DIR__).'/includes/header.php';
?>
<?php $now=date('Y-m-d H:i:s');$soon=date('Y-m-d H:i:s',strtotime('+7 days'));$nUp=0;$nSoon=0;$nOver=0;foreach($rows as $r){if($r['due_at']<$now)$nOver++;else{$nUp++;if($r['due_at']<=$soon)$nSoon++;}} ?>
<?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<div class="row g-3 mb-3">
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Upcoming</div><div class="stat-value text-blue"><?= (int)$nUp ?></div><small class="stat-sub">Not yet due</small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Due within 7 days</div><div class="stat-value text-green"><?= (int)$nSoon ?></div><small class="stat-sub">Accepting work</small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Overdue</div><div class="stat-value text-red"><?= (int)$nOver ?></div><small class="stat-sub">Follow-up required</small></div></div>
  <div class="col-sm-6 col-xl-3"><div class="stat-card"><div class="stat-label">Total deadlines</div><div class="stat-value" style="color:var(--muted)"><?= count($rows) ?></div><small class="stat-sub">All sessions</small></div></div>
</div>
<section class="card filter-bar mb-3"><div class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input type="search" class="form-control" placeholder="Search records..." aria-label="Search deadlines" data-live-filter="#deadlineTable tbody tr"></label><div class="filter-selects"><select class="form-select" aria-label="Filter by state" data-column-filter="5" data-filter-target="#deadlineTable"><option value="">All Deadline States</option><option>Upcoming</option><option>Overdue</option></select></div><a class="btn btn-danger ms-auto" href="#newDeadline">+ Create Deadline</a></div></section>
<section class="card p-4 mb-3"><h2 class="section-heading">Project Deadline Register</h2><div class="table-responsive"><table class="table table-soft" id="deadlineTable"><thead><tr><th>Deadline title</th><th>Stage</th><th>Session</th><th>Department</th><th>Due</th><th>State</th></tr></thead><tbody>
<?php foreach($rows as $r): ?><tr><td class="fw-bold"><?= e($r['title']) ?></td><td><?= e(ui_label($r['milestone_key'])) ?></td><td class="text-muted"><?= e($r['session_name']) ?></td><td><?= e($r['department']??'All departments') ?></td><td class="text-nowrap"><?= e(ui_date($r['due_at'],'M j, Y · g:i A')) ?></td><td><?= $r['due_at']<date('Y-m-d H:i:s')?'<span class="ui-pill is-bad">Overdue</span>':'<span class="ui-pill is-info">Upcoming</span>' ?></td></tr><?php endforeach; ?>
<?php if(!$rows): ?><tr><td colspan="6"><div class="empty-state">No deadlines have been set yet.</div></td></tr><?php endif; ?></tbody></table></div></section>
<section class="card p-4" id="newDeadline"><h2 class="section-heading">Create Deadline</h2><p class="text-muted small">Set the due date for a project stage. Department HODs can create deadlines for their own department; shared deadlines remain visible.</p>
<form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-2"><label class="form-label">Session</label><select class="form-select" name="academic_session_id" required><?php foreach($sessions as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Stage</label><select class="form-select" name="milestone_key" required><?php foreach(['idea','proposal','chapter_1','chapter_2','chapter_3','chapter_4','chapter_5','final_submission','evaluation'] as $k): ?><option value="<?= e($k) ?>"><?= e(ui_label($k)) ?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Title</label><input class="form-control" name="title" required maxlength="160"></div><div class="col-md-2"><label class="form-label">Department</label><select class="form-select" name="department_id" <?= $ownDept?'disabled':'' ?>><?php if(!$ownDept): ?><option value="">All departments</option><?php endif; ?><?php foreach($departments as $d): ?><option value="<?= (int)$d['id'] ?>"><?= e($d['name']) ?><?= $ownDept?' (my department)':'' ?></option><?php endforeach; ?></select></div><div class="col-md-2"><label class="form-label">Due date</label><input class="form-control" type="datetime-local" name="due_at" required></div><div class="col-md-1 d-flex align-items-end"><button class="btn btn-primary w-100">Add</button></div></div></form></section>
